#!/usr/bin/env python3
"""Regenerate vendor/ndt7-workers-embedded.js from the pinned upstream workers.

Browsers block Worker files on file:// pages, but allow ordinary script tags and
Blob workers. Embedding the worker source lets speed_monitor.html run with no server.
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
sources = {
    name: (root / f'ndt7-{name}-worker.js').read_text(encoding='utf-8')
    for name in ('download', 'upload')
}
out = root / 'vendor' / 'ndt7-workers-embedded.js'
out.write_text(
    '// Generated by vendor/build_embedded_workers.py. Do not edit.\n'
    f'window.NDT7_WORKER_SOURCES={json.dumps(sources)};\n',
    encoding='utf-8',
)
print(f'wrote {out}')
